    ///Link a Post (left) and a Tag (right) in the junction table.
    pub fn link_post_tag(&mut self, left: Uuid, right: Uuid) {
        self.post_tag_link.link(left, right);
    }
    ///Remove the link between a Post (left) and a Tag (right).  Returns `true` if a live link existed.  Traversal (`post_tags` / `tag_posts`) stops resolving the pair afterwards.
